"'$f2 = "E:'"\\codex-LOOP\\codex-loop-s-f2\"

# Get SHA256 of the key files in baseline vs F2
"'$sharedFiles = @(
    "harness/agent_router.py","harness/budget_controller.py","harness/dispatch_v2.py",
    "harness/l2_consumer.py","harness/layered_gate.py","harness/lifecycle_supervisor_v2.py",
    "harness/orchestration_common.py","harness/refill_controller_v2.py","harness/result_reducer.py",
    "harness/root_turn_governor.py","harness/short_result_validator.py","harness/statemachine_v2.py",
    "harness/trigger_eval_v2.py","hooks/sol_tool_gate_v2.py","metering/model_token_share_v2.py",
    "config/loop_config_v2.toml","config/orchestration_policy_v2.toml","config/refill_policy.toml",
    "config/roles_v2.yaml","config/statemachine_v2_transitions.json","config/triggers_v2.yaml"
)

