    $fFile = "$fable'"\\"'$relFixed"
    $f2File = "$f2'"\\"'$relFixed"

    $bExists = Test-Path $bFile
    $fExists = Test-Path $fFile
    $f2Exists = Test-Path $f2File

    if (-not $bExists) { 
        Write-Host "MISSING_BASELINE: $rel"
        continue
    }

    $bHash = (Get-FileHash $bFile -Algorithm SHA256).Hash.Substring(0,8)
    $fHash = if ($fExists) { (Get-FileHash $fFile -Algorithm SHA256).Hash.Substring(0,8) } else { "MISSING" }
    $f2Hash = if ($f2Exists) { (Get-FileHash $f2File -Algorithm SHA256).Hash.Substring(0,8) } else { "MISSING" }

    if ($bHash -eq $fHash -and $bHash -eq $f2Hash) {
        Write-Host "3-SAME: $rel"
    } elseif ($bHash -eq $fHash -and $bHash -ne $f2Hash) {
        Write-Host "F2-DIFFERS: $rel (baseline=fable=$bHash, f2=$f2Hash)"
    } elseif ($bHash -eq $f2Hash -and $bHash -ne $fHash) {
        Write-Host "FABLE-DIFFERS: $rel (baseline=f2=$bHash, fable=$fHash)"
    } elseif ($fHash -eq $f2Hash -and $bHash -ne $fHash) {
        Write-Host "BASELINE-DIFFERS: $rel (fable=f2=$fHash, baseline=$bHash)"
    } else {
        Write-Host "ALL-DIFFER: $rel (baseline=$bHash, fable=$fHash, f2=$f2Hash)"
    }
}'

